import React, { useState, useEffect } from "react";

function TripList({ onSelect, onCreate, refreshTrigger }) {
  const [trips, setTrips] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTrips();
  }, [refreshTrigger]);

  const fetchTrips = async () => {
    setLoading(true);
    try {
      const response = await fetch("http://127.0.0.1:5000/api/trips");
      const data = await response.json();
      setTrips(data);
    } catch (err) {
      console.error("Virhe haettaessa tripejä:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id, e) => {
    e.stopPropagation();
    if (!window.confirm("Haluatko varmasti poistaa keikan? Siihen yhdistetyt Orderit vapautuvat.")) return;
    try {
      const response = await fetch(`http://127.0.0.1:5000/api/trips/${id}`, {
        method: "DELETE"
      });
      if (response.ok) {
        fetchTrips();
      } else {
        const data = await response.json();
        alert(data.error || "Poisto epäonnistui");
      }
    } catch (err) {
      alert("Virhe poistossa");
    }
  };

  const statusColor = (status) => {
    if (status === "Suunniteltu") return "#3b82f6";
    if (status === "Vahvistettu") return "#eab308";
    if (status === "Käynnissä") return "#f97316";
    if (status === "Toimitettu") return "#22c55e";
    if (status === "Laskutettu") return "#475569";
    return "#94a3b8";
  };

  const formatRoute = (trip) => {
    const start = trip.first_pickup_city
      ? `${trip.first_pickup_country || ""} ${trip.first_pickup_city}`.trim()
      : "—";
    const end = trip.trip_end_city
      ? `${trip.trip_end_country || ""} ${trip.trip_end_city}`.trim()
      : "—";
    return `${start} → ${end}`;
  };

  return (
    <div>
      <div style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        marginBottom: "20px"
      }}>
        <h2 style={{ color: "#f97316", margin: 0 }}>🚛 Keikat (Trips)</h2>
        <button
          onClick={onCreate}
          style={{
            background: "#22c55e",
            color: "#fff",
            border: "none",
            padding: "10px 20px",
            borderRadius: "8px",
            cursor: "pointer",
            fontWeight: "600",
            fontSize: "14px"
          }}
        >
          + Uusi keikka
        </button>
      </div>

      {loading ? (
        <p style={{ color: "#94a3b8" }}>Ladataan...</p>
      ) : trips.length === 0 ? (
        <div style={{
          background: "rgba(255,255,255,0.03)",
          border: "1px dashed #475569",
          borderRadius: "12px",
          padding: "32px",
          textAlign: "center",
          color: "#94a3b8"
        }}>
          Ei keikkoja. Luo uusi yllä olevasta napista.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          {trips.map(trip => (
            <div
              key={trip.id}
              onClick={() => onSelect(trip.id)}
              style={{
                background: "rgba(255,255,255,0.05)",
                border: "1px solid rgba(255,255,255,0.1)",
                borderRadius: "10px",
                padding: "16px 20px",
                cursor: "pointer",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                transition: "all 0.2s"
              }}
              onMouseEnter={(e) => e.currentTarget.style.borderColor = "#f97316"}
              onMouseLeave={(e) => e.currentTarget.style.borderColor = "rgba(255,255,255,0.1)"}
            >
              <div style={{ flex: 1 }}>
                <div style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                  marginBottom: "8px"
                }}>
                  <span style={{
                    color: "#f97316",
                    fontWeight: "700",
                    fontSize: "16px"
                  }}>
                    {trip.trip_id}
                  </span>
                  <span style={{
                    background: statusColor(trip.status),
                    color: "#fff",
                    padding: "3px 12px",
                    borderRadius: "12px",
                    fontSize: "11px",
                    fontWeight: "600"
                  }}>
                    {trip.status}
                  </span>
                  <span style={{
                    color: "#cbd5e1",
                    fontSize: "13px",
                    background: "rgba(255,255,255,0.05)",
                    padding: "2px 10px",
                    borderRadius: "10px"
                  }}>
                    📦 {trip.order_count || 0} order{trip.order_count === 1 ? "" : "ia"}
                  </span>
                </div>
                <div style={{ color: "#cbd5e1", fontSize: "14px", marginBottom: "4px" }}>
                  {formatRoute(trip)}
                </div>
                <div style={{ color: "#94a3b8", fontSize: "13px" }}>
                  {trip.carrier_name ? `🏢 ${trip.carrier_name}` : "Ei kuljetusyhtiötä"}
                  {trip.plate_number ? ` · 🚚 ${trip.plate_number} (${trip.trailer_type || "—"})` : ""}
                  {trip.ferry_route ? ` · ⛴️ ${trip.ferry_route}` : ""}
                </div>
              </div>
              <button
                onClick={(e) => handleDelete(trip.id, e)}
                style={{
                  background: "transparent",
                  color: "#fca5a5",
                  border: "1px solid #7f1d1d",
                  padding: "6px 12px",
                  borderRadius: "6px",
                  cursor: "pointer",
                  fontSize: "12px"
                }}
              >
                Poista
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default TripList;
